<template><div class="page"><h2 class="page-title">账单与消费分类</h2><p class="muted">当前支持微信.xlsx；支付宝和银行卡将在后续版本开放。</p><div class="card section"><el-upload drag :auto-upload="false" :limit="1" accept=".xlsx" :on-change="f=>selected=f.raw"><p>拖入或选择微信账单</p><small>原文件仅临时解析，导入完成后删除</small></el-upload><el-button class="section" type="primary" :loading="uploading" :disabled="!selected" @click="upload">开始导入</el-button><el-descriptions v-if="report" class="section" border :column="4"><el-descriptions-item label="总记录">{{report.total_rows}}</el-descriptions-item><el-descriptions-item label="新增">{{report.inserted_rows}}</el-descriptions-item><el-descriptions-item label="重复">{{report.duplicate_rows}}</el-descriptions-item><el-descriptions-item label="失败/警告">{{report.failed_rows}} / {{report.warning_rows}}</el-descriptions-item><el-descriptions-item label="消费">{{report.flow_type_counts?.consumption||0}}</el-descriptions-item><el-descriptions-item label="退款">{{report.refund_rows}}</el-descriptions-item><el-descriptions-item label="转账">{{report.transfer_rows}}</el-descriptions-item><el-descriptions-item label="其他/未知">{{report.unknown_flow_rows}}</el-descriptions-item><el-descriptions-item label="未分类笔数占比">{{formatRatio(report.uncategorized_consumption_ratio)}}</el-descriptions-item><el-descriptions-item label="未分类金额占比">{{formatRatio(report.uncategorized_consumption_amount_ratio)}}</el-descriptions-item><el-descriptions-item label="起始时间">{{report.earliest_transaction_time||'暂无'}}</el-descriptions-item><el-descriptions-item label="结束时间">{{report.latest_transaction_time||'暂无'}}</el-descriptions-item></el-descriptions></div><div class="card section"><h3>导入历史</h3><el-table :data="imports" empty-text="尚未导入账单"><el-table-column prop="started_at" label="导入时间"/><el-table-column prop="source" label="来源"/><el-table-column prop="status" label="状态"/><el-table-column prop="inserted_rows" label="新增"/><el-table-column prop="duplicate_rows" label="重复"/><el-table-column prop="failed_rows" label="失败"/></el-table></div><div class="card section"><h3>OTHER 人工审核</h3><p class="muted">优先级只表示建议审核顺序，不代表消费是否必要。语义不足的交易可继续保留为 OTHER。</p><el-table :data="reviews" empty-text="当前没有待审核商户组"><el-table-column prop="tier" label="审核层级"/><el-table-column prop="group_id" label="匿名商户组"/><el-table-column prop="transaction_count" label="笔数"/><el-table-column label="金额"><template #default="s">{{formatMoney(s.row.amount_minor)}}</template></el-table-column></el-table></div><div class="card section"><div class="actions"><h3 style="flex:1">标准交易记录</h3><el-button @click="load">刷新</el-button></div><el-table :data="transactions"><el-table-column prop="occurred_at" label="时间" width="180"/><el-table-column label="金额"><template #default="s">{{formatMoney(s.row.amount_minor)}}</template></el-table-column><el-table-column prop="direction" label="方向"/><el-table-column prop="flow_type" label="类型"/><el-table-column prop="source" label="来源"/><el-table-column prop="status" label="状态"/><el-table-column label="分类"><template #default="s"><el-select :model-value="s.row.effective_category" @change="v=>changeCategory(s.row,v)"><el-option v-for="c in categories" :key="c.code" :label="c.name" :value="c.code"/></el-select><el-tag v-if="s.row.user_confirmed" size="small" type="success">用户已确认</el-tag></template></el-table-column></el-table></div></div></template>
<script setup>
import { onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js'
const selected=ref(),uploading=ref(false),report=ref(),transactions=ref([]),categories=ref([]),imports=ref([]),reviews=ref([])
const formatRatio=value=>`${((value||0)*100).toFixed(1)}%`
async function load(){const [t,c,i,r]=await Promise.all([api.get('/transactions?page_size=100'),api.get('/categories'),api.get('/imports'),api.get('/categories/review')]);transactions.value=t.items;categories.value=c.items;imports.value=i.items;reviews.value=r.items}
async function upload(){const body=new FormData();body.append('file',selected.value);uploading.value=true;try{report.value=await api.post('/imports/wechat',body,{timeout:120000});ElMessage.success('导入完成');await load()}catch(e){ElMessage.error(e.message);if(e.code==='REQUEST_TIMEOUT')await load()}finally{uploading.value=false}}
async function changeCategory(row,code){try{await api.patch(`/transactions/${row.id}/category`,{category_code:code});row.effective_category=code;row.user_confirmed=true;ElMessage.success('分类已确认')}catch(e){ElMessage.error(e.message)}}
onMounted(load)
</script>
